import json, sys
sys.path.insert(0, '.')
from eval.evaluator import DocREDEvaluator

TRAIN_PATH = '/root/autodl-tmp/data/docred/train_annotated.json'
evaluator = DocREDEvaluator.from_train_file(TRAIN_PATH)

pairs = {
    'Qwen3-8B': {
        'we': '/root/autodl-tmp/eval_results/qwen3_8b_sft_eval/predictions.json',
        'ne': '/root/autodl-tmp/eval_results/qwen3_8b_no_evidence_eval_v2/predictions.json',
    },
    'LLaMA-8B': {
        'we': '/root/autodl-tmp/eval_results/llama_3_1_8b_sft_eval/predictions.json',
        'ne': '/root/autodl-tmp/eval_results/llama_3_1_8b_no_evidence_eval/predictions.json',
    },
}

def agg_eval(preds, doc_ids, evaluator):
    ids = set(doc_ids)
    sp, sg = [], []
    for p in preds:
        if p['doc_id'] not in ids: continue
        for t in p['parsed_triples']:
            if isinstance(t, dict):
                sp.append({'doc_id': p['doc_id'], 'head': t.get('head',''), 'tail': t.get('tail',''), 'relation': t.get('relation','')})
        for t in p['gold_triples']:
            if isinstance(t, dict):
                sg.append({'doc_id': p['doc_id'], 'head': t.get('head',''), 'tail': t.get('tail',''), 'relation': t.get('relation','')})
    return evaluator.compute_f1(sp, sg)

for name, paths in pairs.items():
    with open(paths['we']) as f: we = json.load(f)
    with open(paths['ne']) as f: ne = json.load(f)

    we_trunc = set(p['doc_id'] for p in we if p['truncated'])
    ne_trunc = set(p['doc_id'] for p in ne if p['truncated'])
    fair = [p['doc_id'] for p in ne if p['doc_id'] not in (we_trunc | ne_trunc)]

    we_m = agg_eval(we, fair, evaluator)
    ne_m = agg_eval(ne, fair, evaluator)

    # per-doc avg F1
    f1s_we, f1s_ne = [], []
    ids = set(fair)
    for label_preds, f1s in [(we, f1s_we), (ne, f1s_ne)]:
        for p in label_preds:
            if p['doc_id'] not in ids: continue
            ps = set()
            gs = set()
            for t in p['parsed_triples']:
                if isinstance(t, dict):
                    ps.add((t.get('head','').lower().strip(), t.get('tail','').lower().strip(), t.get('relation','').lower().strip()))
            for t in p['gold_triples']:
                if isinstance(t, dict):
                    gs.add((t.get('head','').lower().strip(), t.get('tail','').lower().strip(), t.get('relation','').lower().strip()))
            if not gs: continue
            tp = len(ps & gs)
            pr = tp/len(ps) if ps else 0
            rc = tp/len(gs) if gs else 0
            f1 = 2*pr*rc/(pr+rc) if (pr+rc) > 0 else 0
            f1s.append(f1)

    pdf_we = sum(f1s_we)/len(f1s_we)
    pdf_ne = sum(f1s_ne)/len(f1s_ne)

    print(f'{name} ({len(fair)} docs):')
    print(f'  ign_f1:      WE={we_m[\"ign_f1\"]:.4f} NE={ne_m[\"ign_f1\"]:.4f} Tax={(ne_m[\"ign_f1\"]-we_m[\"ign_f1\"])*100:+.2f}pp')
    print(f'  per-doc F1:  WE={pdf_we:.4f} NE={pdf_ne:.4f} Tax={(pdf_ne-pdf_we)*100:+.2f}pp')
